<script setup lang="ts">type Item={id:string;location:string;label:string;url:string;icon:string|null;newWindow:boolean;position:number;parentId:string|null;children?:Item[]};definePageMeta({layout:'admin',middleware:'admin'});const {data,refresh}=await useFetch<Item[]>('/api/admin/navigation');const csrf=useCsrf();const open=ref(false);const edit=ref<Item|null>(null);const model=reactive({location:'header',label:'',url:'/',icon:'',newWindow:false,position:0,parentId:''});function start(row?:Item){edit.value=row||null;Object.assign(model,{location:row?.location||'header',label:row?.label||'',url:row?.url||'/',icon:row?.icon||'',newWindow:row?.newWindow||false,position:row?.position||0,parentId:row?.parentId||''});open.value=true}async function save(){await $fetch(edit.value?`/api/admin/navigation/${edit.value.id}`:'/api/admin/navigation',{method:edit.value?'PUT':'POST',headers:csrf.value,body:{...model,parentId:model.parentId||null}});open.value=false;await refresh()}async function remove(row:Item){try{await $fetch(`/api/admin/navigation/${row.id}`,{method:'DELETE',headers:csrf.value});await refresh()}catch{alert('先移除子菜单，再删除父项')}}async function shift(row:Item,d:number){const group=(data.value||[]).filter(i=>i.location===row.location&&!i.parentId);const index=group.findIndex(i=>i.id===row.id);const dest=group[index+d];if(!dest)return;await Promise.all([ $fetch(`/api/admin/navigation/${row.id}`,{method:'PUT',headers:csrf.value,body:{...row,position:dest.position}}),$fetch(`/api/admin/navigation/${dest.id}`,{method:'PUT',headers:csrf.value,body:{...dest,position:row.position}})]);await refresh()}</script><template><div><div class="flex justify-between"><h1 class="text-3xl font-semibold">导航</h1><button class="rounded-full px-5 py-2 text-white" style="background:var(--accent)" @click="start()">新增菜单项</button></div><section v-for="place in ['header','footer']" :key="place" class="mt-8"><h2 class="text-xl font-semibold">{{place==='header'?'Header':'Footer'}}</h2><div v-for="i in (data||[]).filter(x=>x.location===place&&!x.parentId)" :key="i.id" class="mt-3 rounded-xl border p-4" style="border-color:var(--border)"><div class="flex justify-between"><div>{{i.icon}} {{i.label}} <span class="text-sm" style="color:var(--muted)">{{i.url}}</span></div><div class="flex gap-3"><button @click="shift(i,-1)">↑</button><button @click="shift(i,1)">↓</button><button @click="start(i)">编辑</button><button @click="remove(i)">删除</button></div></div><div v-for="c in (data||[]).filter(x=>x.parentId===i.id)" :key="c.id" class="ml-6 mt-2 flex justify-between text-sm">↳ {{c.label}} — {{c.url}}<span><button @click="start(c)">编辑</button> <button @click="remove(c)">删除</button></span></div></div></section><div v-if="open" class="fixed inset-0 z-50 grid place-items-center bg-black/50 p-4" @click.self="open=false"><form class="w-full max-w-lg rounded-2xl p-6" style="background:var(--surface)" @submit.prevent="save"><h2 class="text-xl font-semibold">{{edit?'编辑':'新增'}}菜单项</h2><div class="mt-4 grid gap-3"><select v-model="model.location" class="rounded border bg-transparent p-2"><option value="header">Header</option><option value="footer">Footer</option></select><input v-model="model.label" required placeholder="Label" class="rounded border bg-transparent p-2"><input v-model="model.url" required placeholder="URL（站内 /path 或 HTTPS）" class="rounded border bg-transparent p-2"><input v-model="model.icon" placeholder="图标文本" class="rounded border bg-transparent p-2"><select v-model="model.parentId" class="rounded border bg-transparent p-2"><option value="">顶级菜单</option><option v-for="p in (data||[]).filter(x=>x.location===model.location&&!x.parentId&&x.id!==edit?.id)" :key="p.id" :value="p.id">子项归入 {{p.label}}</option></select><label><input v-model="model.newWindow" type="checkbox"> 新窗口打开</label></div><div class="mt-5 flex justify-end gap-3"><button type="button" @click="open=false">取消</button><button class="rounded-lg px-4 py-2 text-white" style="background:var(--accent)">保存</button></div></form></div></div></template>
